"use server";

/**
 * Registers a webhook endpoint; plan and flag gated.
 *
 * Owner D. Two independent gates: the `webhooks` feature flag (which is itself
 * plan-derived) and the numeric `webhooks` quota. Both are checked because a
 * flag can be force-enabled through an org override while the quota still
 * applies.
 *
 * Must call (do not reimplement): createWebhookSchema, can, isEnabled,
 * getPlanLimits, getActor, toActionResult
 */

import {
  FeatureUnavailableError,
  ForbiddenActionError,
  PlanLimitError,
} from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { getPlanLimits } from "@/config/plan-limits";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { createWebhookSchema, type CreateWebhookInput } from "@/schemas/webhook";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { createWebhook, listWebhooks } from "@/server/services/webhook-service";
import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
import type { ActionResult } from "@/types/api";

const run = withAction<typeof createWebhookSchema, WebhookEndpointRow>(
  createWebhookSchema,
  async (raw, actor) => {
    const input = raw as CreateWebhookInput;

    const allowed = can(actor, "webhook:manage", {
      kind: "webhook",
      orgId: input.orgId,
      webhookId: null,
    });
    if (!allowed) {
      throw new ForbiddenActionError("webhook:manage");
    }

    const { organization } = await getOrganizationSummary(actor, input.orgId);
    if (!isEnabled("webhooks", buildFlagContext(actor, organization))) {
      throw new FeatureUnavailableError("webhooks");
    }

    const limits = getPlanLimits(organization.plan);
    const existing = await listWebhooks(actor, input.orgId);
    if (existing.length >= limits.webhooks) {
      throw new PlanLimitError("webhooks", limits.webhooks, existing.length);
    }

    const endpoint = await createWebhook(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.hours);
    return endpoint;
  },
  { revalidate: ["webhooks"], cacheProfile: "hours" },
);

export async function createWebhookAction(
  raw: unknown,
): Promise<ActionResult<WebhookEndpointRow>> {
  return run(raw);
}
"use server";

/**
 * Removes an endpoint.
 *
 * Owner D. Unlike creation this is not flag-gated — an org that loses the
 * `webhooks` capability on a downgrade must still be able to clean up the
 * endpoints it already has.
 *
 * Must call (do not reimplement): deleteWebhookSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { deleteWebhookSchema, type DeleteWebhookInput } from "@/schemas/webhook";
import { deleteWebhook } from "@/server/services/webhook-service";
import type { ActionResult } from "@/types/api";

const run = withAction<typeof deleteWebhookSchema, null>(
  deleteWebhookSchema,
  async (raw, actor) => {
    const input = raw as DeleteWebhookInput;

    const allowed = can(actor, "webhook:manage", {
      kind: "webhook",
      orgId: input.orgId,
      webhookId: input.webhookId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("webhook:manage");
    }

    await deleteWebhook(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.hours);
    return null;
  },
  { revalidate: ["webhooks"], cacheProfile: "hours" },
);

export async function deleteWebhookAction(raw: unknown): Promise<ActionResult<null>> {
  return run(raw);
}
import { z } from "zod";
import { orgIdSchema, webhookIdSchema } from "./common";

export const webhookEventTypeSchema = z.enum([
  "issue.created",
  "issue.updated",
  "issue.status_changed",
  "issue.assigned",
  "comment.created",
  "member.joined",
  "project.created",
  "project.archived",
  "billing.plan_changed",
]);

export const createWebhookSchema = z.object({
  orgId: orgIdSchema,
  url: z.url().max(2_000),
  eventTypes: z.array(webhookEventTypeSchema).min(1).max(20),
});

export const updateWebhookSchema = z.object({
  orgId: orgIdSchema,
  webhookId: webhookIdSchema,
  url: z.url().max(2_000).optional(),
  eventTypes: z.array(webhookEventTypeSchema).min(1).max(20).optional(),
  enabled: z.boolean().optional(),
});

export const deleteWebhookSchema = z.object({
  orgId: orgIdSchema,
  webhookId: webhookIdSchema,
});

/** Body accepted by the inbound webhook receiver route handler. */
export const inboundWebhookSchema = z.object({
  source: z.enum(["billing", "email", "ci"]),
  eventId: z.string().min(1).max(128),
  occurredAt: z.iso.datetime(),
  payload: z.record(z.string(), z.unknown()).default({}),
});

export type CreateWebhookInput = z.infer<typeof createWebhookSchema>;
export type UpdateWebhookInput = z.infer<typeof updateWebhookSchema>;
export type DeleteWebhookInput = z.infer<typeof deleteWebhookSchema>;
export type InboundWebhookInput = z.infer<typeof inboundWebhookSchema>;
"use client";

/**
 * Endpoint list plus the "add endpoint" form.
 *
 * Owner D. Private to the webhooks route. The event-type checkboxes are driven
 * by `webhookEventTypeSchema` so the list of subscribable events cannot drift
 * from what the server will accept.
 */

import { useActionState } from "react";
import { fieldErrorsFromZod } from "@/lib/errors";
import { createWebhookSchema, webhookEventTypeSchema } from "@/schemas/webhook";
import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
import type { ActionResult } from "@/types/api";
import type { OrgId, WebhookId } from "@/types/common";

export type WebhookManagerProps = {
  orgId: OrgId;
  endpoints: readonly WebhookEndpointRow[];
  atLimit: boolean;
  onCreate: (input: unknown) => Promise<ActionResult<WebhookEndpointRow>>;
  onDelete: (input: unknown) => Promise<ActionResult<null>>;
};

type CreateState = ActionResult<WebhookEndpointRow> | null;

const EVENT_TYPES = webhookEventTypeSchema.options;

export function WebhookManager(props: WebhookManagerProps) {
  const { orgId, endpoints, atLimit, onCreate, onDelete } = props;

  const [state, submit, pending] = useActionState<CreateState, FormData>(
    async (_previous, formData) => {
      const parsed = createWebhookSchema.safeParse({
        orgId,
        url: String(formData.get("url") ?? ""),
        eventTypes: formData.getAll("eventTypes").map(String),
      });

      if (!parsed.success) {
        return {
          ok: false,
          error: {
            code: "validation_failed",
            message: "Check the endpoint details.",
            fieldErrors: fieldErrorsFromZod(parsed.error),
          },
        };
      }

      return onCreate(parsed.data);
    },
    null,
  );

  const fieldErrors = state?.ok === false ? (state.error.fieldErrors ?? {}) : {};

  return (
    <div className="space-y-8">
      <ul className="space-y-2">
        {endpoints.map((endpoint) => (
          <li
            key={endpoint.id}
            className="flex items-start gap-4 rounded-md border border-slate-200 bg-white px-4 py-3 text-sm"
          >
            <div className="min-w-0 flex-1">
              <p className="truncate font-medium">{endpoint.url}</p>
              <p className="mt-0.5 text-xs text-slate-500">
                {endpoint.enabled ? "Enabled" : "Disabled"} · {endpoint.eventTypes}
              </p>
            </div>
            <button
              type="button"
              onClick={() => {
                void onDelete({ orgId, webhookId: endpoint.id as WebhookId });
              }}
              className="text-xs text-rose-600"
            >
              Delete
            </button>
          </li>
        ))}
      </ul>

      <form action={submit} className="space-y-4 border-t border-slate-200 pt-6">
        <h2 className="text-sm font-semibold">Add an endpoint</h2>

        {atLimit ? (
          <p className="rounded bg-amber-50 px-3 py-2 text-sm text-amber-800">
            This plan&apos;s webhook quota is full. Delete one first, or upgrade.
          </p>
        ) : null}

        {state?.ok === false && state.error.code === "plan_limit_exceeded" ? (
          <p role="alert" className="rounded bg-rose-50 px-3 py-2 text-sm text-rose-700">
            {state.error.message}
          </p>
        ) : null}

        <div className="space-y-1">
          <label htmlFor="url" className="text-sm font-medium">
            Endpoint URL
          </label>
          <input
            id="url"
            name="url"
            type="url"
            required
            disabled={atLimit}
            placeholder="https://example.com/hooks/taskflow"
            className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm disabled:bg-slate-100"
          />
          {fieldErrors.url !== undefined ? (
            <p className="text-xs text-rose-600">{fieldErrors.url[0]}</p>
          ) : null}
        </div>

        <fieldset className="space-y-2">
          <legend className="text-sm font-medium">Events</legend>
          <div className="grid gap-1 sm:grid-cols-2">
            {EVENT_TYPES.map((eventType) => (
              <label key={eventType} className="flex items-center gap-2 text-sm">
                <input
                  type="checkbox"
                  name="eventTypes"
                  value={eventType}
                  disabled={atLimit}
                />
                {eventType}
              </label>
            ))}
          </div>
          {fieldErrors.eventTypes !== undefined ? (
            <p className="text-xs text-rose-600">{fieldErrors.eventTypes[0]}</p>
          ) : null}
        </fieldset>

        <button
          type="submit"
          disabled={atLimit || pending}
          className="rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white disabled:opacity-60"
        >
          {pending ? "Adding…" : "Add endpoint"}
        </button>
      </form>
    </div>
  );
}
/**
 * Cron-style trigger that drains the webhook queue.
 *
 * Owner D. Deliveries are queued by a subscriber to
 * `webhook.delivery_requested` and retried here with the backoff the job
 * computes, so a customer's endpoint being down never blocks a mutation.
 *
 * Must call (do not reimplement): runWebhookDeliveryJob
 */

import { assertCronSecret, errorResponse } from "@/app/api/_lib/responses";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";

export const dynamic = "force-dynamic";

export async function POST(request: Request): Promise<Response> {
  try {
    assertCronSecret(request);

    const result = await runWebhookDeliveryJob(new Date());
    return Response.json(result);
  } catch (error) {
    return errorResponse(error);
  }
}

